import os
import boto3
from botocore.exceptions import ClientError

class AWSKeyManagementService:
    def __init__(self, key_id: str = None, region_name: str = None):
        self.key_id = key_id or os.environ.get("AWS_KMS_KEY_ID")
        self.region_name = region_name or os.environ.get("AWS_DEFAULT_REGION", "us-east-1")
        self.client = boto3.client("kms", region_name=self.region_name)

    def encrypt(self, plaintext: bytes) -> bytes:
        try:
            response = self.client.encrypt(
                KeyId=self.key_id,
                Plaintext=plaintext
            )
            return response["CiphertextBlob"]
        except ClientError as e:
            raise RuntimeError(f"AWS KMS encryption failed: {e.response['Error']['Message']}") from e

    def decrypt(self, ciphertext_blob: bytes) -> bytes:
        try:
            response = self.client.decrypt(
                CiphertextBlob=ciphertext_blob
            )
            return response["Plaintext"]
        except ClientError as e:
            raise RuntimeError(f"AWS KMS decryption failed: {e.response['Error']['Message']}") from e
